catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading) {
      return;
   }

	g_form.hideAllFieldMsgs("feel_in_imminent_danger");
	if (newValue == "yes"){
			if (g_lang == "fq"){
				g_form.showErrorBox("feel_in_imminent_danger", "Si votre sécurité physique ou votre bien-être est menacé, appelez le 9-1-1 ou communiquez avec la ligne d'urgence de la Cité parlementaire au 613-992-7000 dès que vous le pouvez");
			}
			else
			{
				g_form.showErrorBox("feel_in_imminent_danger", "Call one of the following number. On the Parliamentary Precinct: Parliamentary Protective Service (PPS) [613-992-7000 or 9-1-1], Outside the Parliament Precinct: 9-1-1 or your local emergency departement");
			}
	}


   //Type appropriate comment here, and begin script below

}
